  /** INDIVIDUAL(개인 신청) / PARTY(파티원 신청) */
  participationType: MyParticipationDtoParticipationType;
  /** PENDING(확보 전) / APPLIED(결제 대기) / CONFIRMED(참가 확정) */
  status: MyParticipationDtoStatus;
